public class Program {
    static class Animal {
        void sound() {
            System.out.println("Animal sound");
        }
    }

    static class Dog extends Animal {
        void sound() {
            System.out.println("Bark");
        }
    }

    public static void main(String[] args) {
        Animal a = new Dog();
        a.sound();
    }
}

